import { useState } from 'react'
import { FileType, Loader2 } from 'lucide-react'
import { DocumentPreview } from './DocumentPreview'
import { PdfViewer } from './PdfViewer'
import { NotReadyError, useCreateExport, waitForJob } from '#/features/export/useExport'
import { Button } from '#/components/ui/button'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '#/components/ui/tabs'
import { useWork } from '#/features/work/WorkProvider'

/** Live approximate preview, plus the real PDF generated by the API on demand. */
export function PreviewPage() {
  const { doc } = useWork()
  const create = useCreateExport()
  const [pdf, setPdf] = useState<ArrayBuffer | null>(null)
  const [status, setStatus] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [tab, setTab] = useState('html')

  const generate = async () => {
    setError(null)
    setStatus('Salvando e pedindo o PDF…')
    try {
      const job = await create.mutateAsync('pdf')
      const done = await waitForJob(job.id, (j) => setStatus(j.status === 'running' ? 'Gerando o PDF…' : 'Na fila…'))
      if (done.status !== 'succeeded' || !done.downloadUrl) throw new Error(done.error ?? 'A exportação falhou.')
      const response = await fetch(done.downloadUrl)
      setPdf(await response.arrayBuffer())
      setTab('pdf')
      setStatus(done.warnings.length > 0 ? done.warnings.join(' ') : null)
    } catch (e) {
      setStatus(null)
      setError(
        e instanceof NotReadyError
          ? `Faltam informações para exportar: ${Object.values(e.errors).flat().join(' ')}`
          : (e as Error).message,
      )
    }
  }

  return (
    <main className="mx-auto grid max-w-5xl gap-4 p-6">
      <Tabs value={tab} onValueChange={(v) => setTab(String(v))}>
        <div className="flex flex-wrap items-center gap-3">
          <TabsList>
            <TabsTrigger value="html">Aproximada (tempo real)</TabsTrigger>
            <TabsTrigger value="pdf" disabled={!pdf}>PDF real</TabsTrigger>
          </TabsList>
          <Button onClick={() => void generate()} disabled={create.isPending || (!!status && !error)}>
            {status && !error ? <Loader2 className="animate-spin" /> : <FileType />} Gerar PDF real
          </Button>
          {status && <span className="text-sm text-muted-foreground" role="status">{status}</span>}
          {error && <span className="text-sm text-destructive" role="alert">{error}</span>}
        </div>
        <TabsContent value="html" className="mt-4">
          <DocumentPreview doc={doc} />
        </TabsContent>
        <TabsContent value="pdf" className="mt-4">
          {pdf && <PdfViewer data={pdf} />}
        </TabsContent>
      </Tabs>
    </main>
  )
}
